 amir=c['lookups']['card/amir'];amir.append(txt('hook-note','Please bring your own 3 mm hook to class.|请带自己的3毫米钩针来上课。','dm',author='creator',sender='creator',receiver='Amir',recipient='Amir',counterpart='Amir',conversation_id='thread-Amir'))
