 c['operations']['printer/commit']={'requires':{'fields':{'proof':{'ready':True}}},'set':{'state':{'parcel':'P14','parcel_ready':True}},'add':[txt('print-result','Fourteen physical lesson sets are now ready as P14. The frozen printed-manifest records the actual proof at this commit, not any later edit.|十四份纸质材料已装P14。printed-manifest冻结的是本次印制校样，不跟后改。','receipt'),field('printed-manifest','Actual P14 printed source manifest|P14实际印制来源清单',{})],'copy':[{'from':'proof','to':'printed-manifest','attributes':['fields']}]}
