 c['operations']['printer/share-audio']={'requires':{'revealed':['format-audio']},'set':{'state':{'audio_recipient':'Bex'}},'add':[field('audio-access','Actual private access granted to Bex for the generated audio snapshot. A later regenerated file needs a new grant; this is not public access.|Bex已获得所生成音频快照的真实私有访问，后来重生成须重新给访问，不是公开。',{})],'copy':[{'from':'format-audio','to':'audio-access','attributes':['fields']}]}
 c['goals'][0]['pass_condition']=T('M4 A is the selected wallet; M4 B is a tote under the same title. Direct P0 plus correct G4-wallet-v4 remains lawful in either configuration without reading unused M4 or first trying a failed original print. For wallet class preserve actual M4 class instructions and its compatible B room; for P0 use actual P0 class pages plus all fourteen correct wallet take-home guides in a compatible A/B room. A higher G5 bag revision cannot replace wallet content.|A的M4为已选钱包，B同标题却是托特包。两配置都可直接P0加正确G4-wallet-v4，不用看未选M4或先打印失败。钱包课保留真M4课堂步骤及B教室；P0须真P0课堂页加十四份正确钱包带回家指南，可A/B。更高G5包版本不能替钱包。')
 c['goals'][1]['pass_condition']=T('Prepare, correct and commit the actual provider proof before claiming P14 ready. The frozen printed-manifest, selected project, real room booking and accepted pickup card must agree; later proof edits cannot repair an already printed parcel. Sol must accept and actually dispatch the correct P14. Existing legal source permissions need no new approval.|声称P14可领前，真实校样须准备、修正并实际印制。冻结印制清单、所选项目、真教室预约及已接取件卡相符；后改校样不能修已印纸包。Sol须接受且真送正确P14，已有来源许可不再求批准。')
