  fixes += [write('old-link',('I checked M4’s actual pages: this is the selected wallet lesson. The corrected source-bound formats are now in the class set.|我核过M4内页，是已选钱包课。材料中的格式版本已按原文件更正。' if wallet else 'The class set now uses P0 practice plus the correct Nori wallet guide. Please use the actual updated files, not just a familiar title.|课堂材料已换P0练习和Nori正确钱包指南，请用真更正文件，别只认熟悉标题。')),write('old-room1','The warm wallet lesson needs B’s ventilation. '+('That original lesson is booked in B.|温热钱包课需要B通风，原课程已经订在B。' if wallet else 'Today’s practice lesson does not use heating and is booked in '+room+'.|今天练习不需要加热，订在'+room+'。')),write('old-room2','A reply to the hook reminder does not confirm the room. The final booking is '+room+'; collect the printed materials there.|回带钩针的提醒不等于确认教室。最终订在'+room+'，印好的材料在那领。')]
