 short=route();alt=route('wallet','B') if branch=='A' else route(room='B');near=deepcopy(short);ni=next(i for i,a in enumerate(near) if a.get('choice')=='patch-proof');near[ni]=dict(near[ni],params={**near[ni]['params'],'large_source':'G5-bag-v5','audio_source':'G5-bag-v5'})
